To compare two Excel files and show discrepancies in Node.js, you can use a library like `xlsx` to read the Excel files and `lodash` for comparison. Here's a simple example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script (e.g., `compareExcel.js`) to read and compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const differences = [];

  keys1.forEach((key1) => {
    const value1 = sheet1[key1].v;
    const key2 = _.findIndex(keys2, (key) => _.startsWith(key, key1)) + 1;

    if (key2 === keys2.length) {
      differences.push({ missing: key1, inFile1: file1 });
    } else {
      const value2 = sheet2[keys2[key2]].v;

      if (value1 !== value2) {
        differences.push({
          key1,
          key2: keys2[key2],
          value1,
          value2,
          inFile1: file1,
          inFile2: file2,
        });
      }
    }
  });

  keys2.forEach((key) => {
    if (!_.includes(keys1, key)) {
      differences.push({
        missing: key,
        inFile1: file1,
        inFile2: file2,
      });
    }
  });

  return differences;
}

// Usage
const file1 = 'file1.xlsx';
const file2 = 'file2.xlsx';
const sheetName = 'Sheet1';

compareFiles(file1, file2, sheetName)
  .then((differences) => {
    console.log('Differences:', differences);
  })
  .catch((error) => {
    console.error('Error:', error);
  });
```

